package entdomain

import (
	"fmt"
	"io"
	"log"
	"os"
	"path/filepath"
	"strings"

	"entgo.io/ent/entc/gen"
)

// generatedMarker is the ownership marker. Every file this extension writes
// starts with a header containing it (see the first line of each template), so
// the marker is not a record kept alongside the output — it is the output.
//
// It is deliberately narrower than ent's own "Code generated by ent, DO NOT
// EDIT.": matching that would make this extension delete ent's files.
const generatedMarker = "Code generated by entdomain extension"

// markerScanBytes bounds how much of a file is read looking for its first line.
// Only that first line is searched: the marker is the header, and the header is
// line one of every template. Searching further would let a file that merely
// mentions the marker in a comment or a string be deleted.
const markerScanBytes = 4096

// generatedFileNames returns the file names this extension can write for node,
// whether or not this run wrote them.
func generatedFileNames(node *gen.Type) []string {
	base := strings.ToLower(node.Name)
	return []string{
		base + "_dto.go",
		base + "_filter.go",
		base + "_wiring.go",
		base + "_base_service.go",
		base + "_base_handler.go",
	}
}

// removeStaleArtifacts deletes files this extension wrote on an earlier run and
// did not write on this one — the entity lost its annotations, or the generator
// that produced the file was switched off.
//
// This deletes files from the consumer's repository, so it is fenced in three
// ways, and all three have to hold:
//
//  1. Only file names this extension itself can produce, for entities present
//     in the schema this run examined. A file for an entity that has been
//     deleted from the schema outright is never considered — the generator has
//     no way to tell it apart from a consumer's own file.
//  2. Only files carrying the entdomain marker in their header. A hand-written
//     file that happens to occupy one of those names survives, as does one
//     whose header has been edited into something else.
//  3. Never a path this run just wrote.
//
// Files left in place because of rule 2 are reported rather than silently
// ignored: from the outside they look exactly like output that failed to be
// cleaned up.
func removeStaleArtifacts(dir string, nodes []*gen.Type, written map[string]bool) error {
	for _, node := range nodes {
		for _, name := range generatedFileNames(node) {
			path := filepath.Join(dir, name)
			if written[path] {
				continue
			}

			owned, err := hasGeneratedMarker(path)
			if err != nil {
				return err
			}
			if !owned {
				continue
			}

			if err := os.Remove(path); err != nil {
				return fmt.Errorf("failed to remove stale generated file %s: %w", path, err)
			}
			log.Printf("entdomain: removed stale generated file %s (%s no longer generates it)", path, node.Name)
		}
	}
	return nil
}

// hasGeneratedMarker reports whether path exists and carries the entdomain
// marker on its first line. A file that exists without it is reported as not
// ours, on the log, and left alone.
func hasGeneratedMarker(path string) (bool, error) {
	f, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return false, nil
		}
		return false, fmt.Errorf("failed to inspect %s: %w", path, err)
	}
	defer func() { _ = f.Close() }()

	head := make([]byte, markerScanBytes)
	n, err := f.Read(head)
	if err != nil && err != io.EOF {
		return false, fmt.Errorf("failed to inspect %s: %w", path, err)
	}
	firstLine, _, _ := strings.Cut(string(head[:n]), "\n")
	if strings.Contains(firstLine, generatedMarker) {
		return true, nil
	}

	log.Printf("entdomain: leaving %s in place — it does not carry the %q header, so this extension did not write it", path, generatedMarker)
	return false, nil
}
